import OpenAI from "openai";

// Portable contract: what the application needs, in its own terms.
interface TriageResult {
  label: "Hardware" | "Software" | "Other" | null;
  status: "ok" | "refused" | "incomplete";
  usage: { inputTokens: number; outputTokens: number };
}

interface TriageProvider {
  triage(ticket: string): Promise<TriageResult>;
}

// OpenAI-specific adapter: Responses items, text.format, refusals, and status stay behind this boundary.
class OpenAITriage implements TriageProvider {
  constructor(private client: OpenAI, private model: string) {}

  async triage(ticket: string): Promise<TriageResult> {
    const r = await this.client.responses.create({
      model: this.model,
      instructions: "Classify the ticket as Hardware, Software, or Other.",
      input: ticket,
      text: { format: { type: "json_schema", name: "triage", strict: true, schema: triageSchema } },
    });
    const usage = { inputTokens: r.usage?.input_tokens ?? 0, outputTokens: r.usage?.output_tokens ?? 0 };
    if (r.status === "incomplete") return { label: null, status: "incomplete", usage };
    const part = r.output.find((item) => item.type === "message")?.content[0];
    if (part?.type === "refusal") return { label: null, status: "refused", usage }; // surfaced, not hidden
    return { label: JSON.parse(r.output_text).label, status: "ok", usage };
  }
}

const model = process.env.OPENAI_MODEL; // verify current ids: https://developers.openai.com/api/docs/models
if (!model) throw new Error("OPENAI_MODEL is not configured");
const provider: TriageProvider = new OpenAITriage(new OpenAI(), model);

import OpenAI from "openai";

const client = new OpenAI(); // reads OPENAI_API_KEY from the environment
const model = process.env.OPENAI_MODEL; // verify current ids: https://developers.openai.com/api/docs/models
if (!model) throw new Error("OPENAI_MODEL is not configured");

// Before (Chat Completions):
//   messages: [{ role: "system", ... }, { role: "user", ... }]
//   response_format: { type: "json_schema", json_schema: { name, strict, schema } }
