// Items, not choices: reasoning, function calls, and messages are separate output types.
if (response.status !== "completed") throw new Error(`Status ${response.status}`);
const result = JSON.parse(response.output_text);

// Lifecycle gate: fail the build when the configured id has an announced shutdown.
// Source: https://developers.openai.com/api/docs/deprecations (reviewed snapshot, with an owner)
const shutdowns = await loadReviewedDeprecationSnapshot();
const entry = shutdowns.get(model);
if (entry) throw new Error(`${model} shuts down ${entry.shutdownDate}; evaluate ${entry.replacement} now`);

// Promotion, hold, and rollback thresholds are declared before any traffic moves.
const thresholds = {
  maxCriticalFailures: 0,
  minWorstSliceDelta: 0, // the candidate may not regress any critical slice
  maxP95LatencyMs: 4_000,
  maxCostRatio: 1.2,
};

// Shadow: the candidate sees a copy of approved traffic. Its output is never shown,
// and it runs without side-effecting tools, so nothing needs reconciling afterwards.
async function handle(request: TriageRequest): Promise<TriageResult> {
  const live = await baseline.triage(request.ticket);
  if (shadowPermitted(request.dataClass)) {
    candidate
      .triage(request.ticket)
      .then((shadowResult) => recordComparison({ version: "candidate-2026-09", requestId: request.id, live, shadowResult }))
      .catch((error) => recordShadowError(request.id, error));
  }
  return live;
}

// Canary: a small, sticky cohort. Rollback is a configuration change.
function route(userId: string): "baseline" | "candidate" {
  const percent = Number(process.env.CANARY_PERCENT ?? "0");
  return stableHashPercent(userId) < percent ? "candidate" : "baseline";
}

function gate(m: { criticalFailures: number; worstSliceDelta: number; p95LatencyMs: number; costRatio: number }) {
  if (m.criticalFailures > thresholds.maxCriticalFailures) return "rollback";
  if (m.p95LatencyMs > thresholds.maxP95LatencyMs || m.costRatio > thresholds.maxCostRatio) return "hold";
  return m.worstSliceDelta >= thresholds.minWorstSliceDelta ? "promote" : "hold";
}

// Routing and prompts are versioned configuration; rollback is a flag flip, not a deploy.
const route = process.env.TRIAGE_ROUTE === "responses" ? "responses" : "chat-completions";
const promptVersion = { "chat-completions": "triage@6", responses: "triage@6-responses" }[route];

// Backward-compatible records: both state shapes are kept until the observation window closes.
interface ConversationRow {
  id: string;
  messages: unknown[]; // legacy shape, read by the old path
  lastResponseId?: string; // Responses chain, when store is enabled
  migratedAt?: string;
}

interface CloseChecklist {
  productionGatesPassed: boolean;
  rollbackRehearsedMinutes: number | null;
  dataReconciled: boolean;
  securityAndPrivacyReviewed: boolean;
  runbooksUpdated: boolean;
  remainingLegacyUse: { usage: string; owner: string; acceptedUntil: string }[];
  residualRiskAcceptedBy: string | null;
  observationWindowEnds: string;
}

function canClose(c: CloseChecklist, today: string) {
  return (
    c.productionGatesPassed &&
    c.rollbackRehearsedMinutes !== null &&
    c.dataReconciled &&
    c.securityAndPrivacyReviewed &&
    c.runbooksUpdated &&
    c.remainingLegacyUse.every((u) => u.owner && u.acceptedUntil) &&
    c.residualRiskAcceptedBy !== null &&
    today >= c.observationWindowEnds
  );
}
// Irreversible cleanup, such as dropping ConversationRow.messages, happens only after canClose() is true.
